/** Fold the input, veto on the family's exclusion vocabulary, then test all
 *  extension classes. The ONLY sanctioned entry point — detectors must not
 *  hand-roll their own folding of these regexes. */
export function extFires(familyId: string, text: string): boolean {
  const ext = FAMILY_EXT[familyId];
  if (!ext) return false;
  const n = normalizeMc(text.toLowerCase());
  if (ext.exclude?.test(n)) return false;
  return (ext.stems?.test(n) ?? false) || (ext.idioms?.test(n) ?? false) || (ext.literals?.test(n) ?? false);
}
